import './Hero.css';
import heroImage from '../assets/image.png';

const Hero = () => {
    return (
        <div className="hero container py-5">
            <h1 className="title text-center mb-4">
                Welcome to our Store
            </h1>

            <div className="hero-image text-center">
                <img
                    src={heroImage}
                    className="img-fluid rounded shadow"
                    alt="Store hero"
                />
            </div>
        </div>
    );
};

export default Hero;
